-- ==============================================================================
-- MIGRATION 169: EMENDAS — CNPJ E DADOS DA RECEITA DOS BENEFICIÁRIOS (SANEAMENTO DE 23/10/2026)
-- Versão: 20261023000169_emendas_beneficiarios_cnpj_receita.sql
--
-- Pesquisa de 23/10/2026, a pedido do coordenador: CNPJ de cada beneficiário, sempre confirmado na Receita Federal
-- (consulta pública por CNPJ) e só quando a ligação é segura. 542 cadastros, em três casos:
--   - CNPJ da unidade: a unidade tem a própria filial na Receita (ex.: 11º BPM/I de Jundiaí = 04.198.514/0002-35),
--     achada pela cidade + número + tipo da unidade. O endereço de entrega vem da filial (só se ainda estiver vazio).
--   - CNPJ do órgão: a corporação estadual (PMESP, PMCE, SEPM-RJ, PC-MS…), sem filial da unidade na Receita. O
--     endereço de entrega fica como está (a sede do órgão não é o endereço da unidade).
--   - CNPJ da prefeitura: Guardas Municipais e Defesas Civis, pelo município que publica compras no PNCP.
-- Os dados da Receita (razão social = nome do beneficiário, natureza jurídica, situação e sede) vão junto, como a
-- tela faz ao buscar o CNPJ. Os 31 cadastros sem ligação segura ficam como estão (nada é excluído).
-- Cada linha só vale para o cadastro que ainda está sem CNPJ: o que a CAEP já preencheu não muda.
-- Antes do CNPJ, 2 pares que caem na mesma filial da Receita, na mesma cidade, são juntados (mesma unidade com
-- nomes diferentes, ex.: "12º Batalhão de Polícia Militar" e "… do Interior" em Botucatu): fica o de nome mais
-- completo, como juntar_beneficiarios_emenda faz.
-- Depende da migration 168 (os ids são os que ficam depois da junção dos repetidos).
-- ==============================================================================

-- 1) Juntar as unidades que são a mesma filial ------------------------------------
CREATE TEMP TABLE juncoes_169 AS
SELECT v.fica_id, v.sai_id, s.nome AS sai_nome, s.cnpj AS sai_cnpj, s.outros_nomes AS sai_outros,
       (SELECT count(*) FROM public.emenda_pedido_linhas l WHERE l.beneficiario_id = v.sai_id) AS linhas
  FROM (VALUES
  ('06b36200-c4b1-47c4-a2f2-4c992910b598'::uuid, '12º Batalhão de Polícia Militar do Interior', '9ea3282a-15f8-4afb-bee3-97369b1fade1'::uuid, '12º Batalhão de Polícia Militar'),
  ('6e0db681-a155-414f-beb4-4a5cfe70d183'::uuid, '24º Batalhão de Polícia Militar Metropolitano', '555b1c54-70bf-4089-8b19-85c482270e13'::uuid, '24º Batalhão de Polícia Militar')
  ) v(fica_id, fica_nome, sai_id, sai_nome)
  JOIN public.emenda_beneficiarios f ON f.id = v.fica_id AND f.nome = v.fica_nome
  JOIN public.emenda_beneficiarios s ON s.id = v.sai_id AND s.nome = v.sai_nome;

UPDATE public.emenda_pedido_linhas l SET beneficiario_id = j.fica_id FROM juncoes_169 j WHERE l.beneficiario_id = j.sai_id;

INSERT INTO public.emenda_beneficiarios_juntados (ficou_id, ficou_nome, saiu_id, saiu_nome, saiu_cnpj, linhas, motivo, juntado_por_nome)
SELECT j.fica_id, f.nome, j.sai_id, j.sai_nome, j.sai_cnpj, j.linhas,
       'Mesma filial na Receita e mesma cidade (saneamento, migration 169)', 'Saneamento pela Receita (migration 169)'
  FROM juncoes_169 j JOIN public.emenda_beneficiarios f ON f.id = j.fica_id;

UPDATE public.emenda_beneficiarios f SET
  outros_nomes = ARRAY(SELECT DISTINCT x FROM unnest(f.outros_nomes || j.sai_outros || ARRAY[j.sai_nome::TEXT]) x WHERE x <> f.nome ORDER BY x),
  sigla = COALESCE(f.sigla, s.sigla)
  FROM juncoes_169 j JOIN public.emenda_beneficiarios s ON s.id = j.sai_id
 WHERE f.id = j.fica_id;

DELETE FROM public.emenda_beneficiarios WHERE id IN (SELECT sai_id FROM juncoes_169);
DROP TABLE juncoes_169;

