UPDATE public.emenda_beneficiarios b SET
  cnpj = r.cnpj,
  razao_social = r.razao_social,
  natureza_juridica = r.natureza_juridica,
  ente_federativo = r.ente_federativo,
  situacao_cadastral = r.situacao_cadastral,
  sede_endereco = r.sede_endereco,
  sede_municipio = r.sede_municipio,
  sede_uf = r.sede_uf,
  sede_cep = r.sede_cep,
  sede_telefone = r.sede_telefone,
  sede_email = r.sede_email,
  receita_lida_em = NOW(),
  entrega_cep = CASE WHEN b.entrega_cep IS NULL AND b.entrega_logradouro IS NULL THEN r.entrega_cep ELSE b.entrega_cep END,
  entrega_logradouro = CASE WHEN b.entrega_cep IS NULL AND b.entrega_logradouro IS NULL THEN r.entrega_logradouro ELSE b.entrega_logradouro END,
  entrega_numero = CASE WHEN b.entrega_cep IS NULL AND b.entrega_logradouro IS NULL THEN r.entrega_numero ELSE b.entrega_numero END,
  entrega_complemento = CASE WHEN b.entrega_cep IS NULL AND b.entrega_logradouro IS NULL THEN r.entrega_complemento ELSE b.entrega_complemento END,
  entrega_bairro = CASE WHEN b.entrega_cep IS NULL AND b.entrega_logradouro IS NULL THEN COALESCE(b.entrega_bairro, r.entrega_bairro) ELSE b.entrega_bairro END,
  versao = b.versao + 1,
  atualizado_por = NULL,
  atualizado_por_nome = 'Saneamento pela Receita (migration 169)',
  atualizado_em = NOW()
FROM receita_169 r
WHERE b.id = r.id AND b.cnpj IS NULL;

DROP TABLE receita_169;
